<script>
"use strict";
const TAU = Math.PI * 2;
const DPR = Math.min(window.devicePixelRatio || 1, 2);

/* ---------- palettes ---------- */
const PAL = {
  hero:   {base:'#e6be5c', hi:'#fff4cf', lo:'#8a5a1a', edge:'#b8860b', deep:'#4e340c', spec:1.0},
  bronze: {base:'#c07b3e', hi:'#ffd8a8', lo:'#5e3312', edge:'#8a4f24', deep:'#341c08', spec:0.75},
  silver: {base:'#c4cad2', hi:'#ffffff', lo:'#5b636b', edge:'#9aa2aa', deep:'#333a41', spec:1.0},
  gold:   {base:'#e4bd47', hi:'#fff6cf', lo:'#7a5a12', edge:'#b8901f', deep:'#412f07', spec:1.0},
  black:  {base:'#2a2a36', hi:'#9a9ac2', lo:'#101018', deep:'#040409', edge:'#3a3a4a', spec:0.85}
};

/* ---------- color helpers ---------- */
function hexToRgb(h){h=h.replace('#','');return [parseInt(h.substr(0,2),16),parseInt(h.substr(2,2),16),parseInt(h.substr(4,2),16)];}
function mix(c1,c2,t){const a=hexToRgb(c1),b=hexToRgb(c2);return 'rgb('+((a[0]+(b[0]-a[0])*t)|0)+','+((a[1]+(b[1]-a[1])*t)|0)+','+((a[2]+(b[2]-a[2])*t)|0)+')';}

/* ---------- face artwork primitives ---------- */
function faceGrad(ctx,R,pal){
  const g=ctx.createRadialGradient(-R*0.28,-R*0.30,R*0.05,-R*0.05,-R*0.05,R*1.15);
  g.addColorStop(0,pal.hi);g.addColorStop(0.40,pal.base);g.addColorStop(0.82,pal.lo);g.addColorStop(1,pal.deep);
  return g;
}
function ringEmboss(ctx,ro,ri,pal){
  const rm=(ro+ri)/2,w=ro-ri;ctx.save();ctx.lineWidth=w;
  ctx.strokeStyle=pal.base;ctx.beginPath();ctx.arc(0,0,rm,0,TAU);ctx.stroke();
  ctx.strokeStyle=pal.hi;ctx.beginPath();ctx.arc(0,0,rm,Math.PI*1.15,Math.PI*1.92);ctx.stroke();
  ctx.strokeStyle=pal.deep;ctx.beginPath();ctx.arc(0,0,rm,Math.PI*0.14,Math.PI*0.92);ctx.stroke();
  ctx.restore();
}
function beadRing(ctx,r,pal,n){
  for(let i=0;i<n;i++){const ang=i/n*TAU;const x=Math.cos(ang)*r,y=Math.sin(ang)*r;
    ctx.beginPath();ctx.arc(x,y,Math.max(1,r*0.014),0,TAU);ctx.fillStyle=(i%2?pal.hi:pal.lo);ctx.fill();}
}
function innerRecess(ctx,r,pal){
  const g=ctx.createRadialGradient(-r*0.2,-r*0.25,r*0.05,0,0,r*1.05);
  g.addColorStop(0,pal.base);g.addColorStop(1,pal.lo);
  ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,r,0,TAU);ctx.fill();
  ctx.lineWidth=Math.max(2,r*0.035);
  ctx.strokeStyle=pal.deep;ctx.beginPath();ctx.arc(0,0,r,Math.PI*0.1,Math.PI*0.95);ctx.stroke();
  ctx.strokeStyle=pal.hi;ctx.beginPath();ctx.arc(0,0,r,Math.PI*1.15,Math.PI*1.95);ctx.stroke();
}
function emboss(ctx,pb,pal,d){
  ctx.save();ctx.translate(d,d);ctx.fillStyle=pal.deep;pb();ctx.fill();ctx.restore();
  ctx.save();ctx.translate(-d,-d);ctx.fillStyle=pal.hi;pb();ctx.fill();ctx.restore();
  ctx.fillStyle=pal.base;pb();ctx.fill();
}
function embossText(ctx,txt,x,y,size,pal,weight){
  ctx.save();ctx.textAlign='center';ctx.textBaseline='middle';
  ctx.font=(weight||'800')+' '+size+'px Georgia,"Times New Roman",serif';
  ctx.fillStyle=pal.deep;ctx.fillText(txt,x+1.6,y+1.6);
  ctx.fillStyle=pal.hi;ctx.fillText(txt,x-1.6,y-1.6);
  ctx.fillStyle=pal.base;ctx.fillText(txt,x,y);
  ctx.restore();
}
function starPath(ctx,r,pts){
  ctx.beginPath();
  for(let i=0;i<pts*2;i++){const ang=i/(pts*2)*TAU-Math.PI/2;const rr=(i%2)?r*0.45:r;
    const x=Math.cos(ang)*rr,y=Math.sin(ang)*rr;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);}
  ctx.closePath();
}
function arcText(ctx,str,radius,centerAngle,arcSpan,size,pal,flip){
  const pass=(dx,dy,col)=>{
    ctx.save();ctx.fillStyle=col;ctx.textAlign='center';ctx.textBaseline='middle';
    ctx.font='700 '+size+'px Georgia,"Times New Roman",serif';
    const n=str.length,per=arcSpan/Math.max(n-1,1);
    for(let i=0;i<n;i++){
      const ang=centerAngle-arcSpan/2+i*per;
      const x=Math.cos(ang)*radius,y=Math.sin(ang)*radius;
      ctx.save();ctx.translate(x+dx,y+dy);
      ctx.rotate(ang+(flip?-Math.PI/2:Math.PI/2));
      ctx.fillText(str[i],0,0);ctx.restore();
    }
    ctx.restore();
  };
  pass(1.2,1.2,pal.deep);pass(-1.2,-1.2,pal.hi);pass(0,0,pal.base);
}

/* ---------- the two coin faces ---------- */
function drawFront(ctx,R,pal){
  ctx.fillStyle=faceGrad(ctx,R,pal);ctx.beginPath();ctx.arc(0,0,R,0,TAU);ctx.fill();
  ringEmboss(ctx,R*0.965,R*0.90,pal);
  beadRing(ctx,R*0.835,pal,64);
  arcText(ctx,'WASTEDTOKEN·MINT',R*0.72,-Math.PI/2,Math.PI*1.18,R*0.115,pal,false);
  arcText(ctx,'FIDELIS·IN·AERE',R*0.72,Math.PI/2,Math.PI*0.82,R*0.082,pal,true);
  innerRecess(ctx,R*0.52,pal);
  emboss(ctx,()=>starPath(ctx,R*0.36,7),pal,1.7);
  embossText(ctx,'WT',0,R*0.02,R*0.30,pal);
}
function drawBack(ctx,R,pal,denom){
  ctx.fillStyle=faceGrad(ctx,R,pal);ctx.beginPath();ctx.arc(0,0,R,0,TAU);ctx.fill();
  ringEmboss(ctx,R*0.965,R*0.90,pal);
  beadRing(ctx,R*0.835,pal,64);
  arcText(ctx,'LEGAL·TENDER·OF·THE·REALM',R*0.72,-Math.PI/2,Math.PI*1.28,R*0.078,pal,false);
  arcText(ctx,'WASTEDTOKEN·MINT',R*0.72,Math.PI/2,Math.PI*0.92,R*0.078,pal,true);
  embossText(ctx,denom,0,-R*0.06,R*0.34,pal);
  embossText(ctx,'TOKENS',0,R*0.30,R*0.14,pal,'700');
  [-R*0.40,R*0.40].forEach(x=>{ctx.save();ctx.translate(x,R*0.0);emboss(ctx,()=>starPath(ctx,R*0.07,5),pal,1);ctx.restore();});
}

/* ---------- 3D coin renderer (orthographic, painter's algorithm) ---------- */
const LIGHT=[-0.3534,0.5049,0.7876];
const HALF =[-0.1869,0.2670,0.9453];
function renderCoin(ctx,cx,cy,R,TH,a,b,pal,frontFn,backFn){
  const ca=Math.cos(a),sa=Math.sin(a),cb=Math.cos(b),sb=Math.sin(b);
  const ex=[cb,0,-sb], ey=[sb*sa,ca,cb*sa], ez=[sb*ca,-sa,cb*ca];
  const nz=ez[2];

  function paintFace(isFront){
    const s=isFront?1:-1;
    const fcx=ez[0]*TH/2*s, fcy=ez[1]*TH/2*s;
    const mx=isFront?1:-1;
    const diff=Math.max(0, ez[0]*s*LIGHT[0]+ez[1]*s*LIGHT[1]+ez[2]*s*LIGHT[2]);
    const shadeF=0.30+0.70*diff;
    ctx.save();
    ctx.setTransform(mx*ex[0], -mx*ex[1], -ey[0], ey[1], cx+fcx, cy-fcy);
    ctx.beginPath();ctx.arc(0,0,R,0,TAU);ctx.clip();
    if(isFront)frontFn(ctx,R,pal);else backFn(ctx,R,pal);
    // diffuse dimming as the face turns from the light
    ctx.globalCompositeOperation='source-over';
    ctx.fillStyle='rgba(0,0,0,'+((1-shadeF)*0.72)+')';
    ctx.fillRect(-R,-R,2*R,2*R);
    // raking specular highlight — sweeps across as the coin spins about the vertical axis
    ctx.globalCompositeOperation='lighter';
    const cbnd=Math.sin(b)*R*0.85;
    const g=ctx.createLinearGradient(cbnd-R*0.9,0,cbnd+R*0.9,0);
    g.addColorStop(0,'rgba(255,255,255,0)');
    g.addColorStop(0.5,'rgba(255,248,232,'+(0.6*pal.spec)+')');
    g.addColorStop(1,'rgba(255,255,255,0)');
    ctx.fillStyle=g;ctx.fillRect(-R,-R,2*R,2*R);
    ctx.globalCompositeOperation='source-over';
    ctx.restore();
  }

  function rimPt(phi,side){
    const cf=Math.cos(phi),sf=Math.sin(phi);
    const wx=R*cf*ex[0]+R*sf*ey[0]+side*ez[0]*TH/2;
    const wy=R*cf*ex[1]+R*sf*ey[1]+side*ez[1]*TH/2;
    return [cx+wx, cy-wy];
  }
  function drawRim(){
    ctx.setTransform(1,0,0,1,0,0);
    const N=176, NR=120, segs=[];
    for(let i=0;i<N;i++){
      const f0=i/N*TAU,f1=(i+1)/N*TAU,fm=(f0+f1)/2;
      const cf=Math.cos(fm),sf=Math.sin(fm);
      const nrm=[cf*ex[0]+sf*ey[0], cf*ex[1]+sf*ey[1], cf*ex[2]+sf*ey[2]];
      if(nrm[2]<=0.015) continue;                 // only the viewer-facing rim band
      const wz=R*cf*ex[2]+R*sf*ey[2];
      segs.push([f0,f1,fm,nrm,wz]);
    }
    segs.sort((p,q)=>p[4]-q[4]);
    for(const s of segs){
      const nrm=s[3];
      const diff=Math.max(0,nrm[0]*LIGHT[0]+nrm[1]*LIGHT[1]+nrm[2]*LIGHT[2]);
      const spec=Math.pow(Math.max(0,nrm[0]*HALF[0]+nrm[1]*HALF[1]+nrm[2]*HALF[2]),14);
      const ridge=0.5+0.5*Math.pow(0.5+0.5*Math.sin(s[2]*NR),1.4);   // the reeding
      let shade=(0.13+0.72*diff)*ridge + spec*0.9*pal.spec;
      shade=Math.max(0,Math.min(1,shade));
      const p0f=rimPt(s[0],1),p1f=rimPt(s[1],1),p1b=rimPt(s[1],-1),p0b=rimPt(s[0],-1);
      ctx.fillStyle=mix(pal.deep,pal.hi,shade);
      ctx.beginPath();ctx.moveTo(p0f[0],p0f[1]);ctx.lineTo(p1f[0],p1f[1]);
      ctx.lineTo(p1b[0],p1b[1]);ctx.lineTo(p0b[0],p0b[1]);ctx.closePath();ctx.fill();
    }
  }

  if(nz>=0){ paintFace(false); drawRim(); paintFace(true); }
  else     { paintFace(true);  drawRim(); paintFace(false); }
  ctx.setTransform(1,0,0,1,0,0);
}

/* ===================== HERO ===================== */
const canvas=document.getElementById('coin-hero');
const ctx=canvas.getContext('2d');
let lastT=0;

function drawFrontHero(c,R,p){drawFront(c,R,p);}
function drawBackHero(c,R,p){drawBack(c,R,p,'10,000');}

function render(t){
  lastT=t;
  const W=canvas.width,H=canvas.height;
  if(W===0||H===0) return;
  ctx.setTransform(1,0,0,1,0,0);
  // simple backdrop — only the coin lives here
  const bg=ctx.createRadialGradient(W/2,H*0.44,10,W/2,H*0.5,Math.max(W,H)*0.72);
  bg.addColorStop(0,'#20222c');bg.addColorStop(0.5,'#111219');bg.addColorStop(1,'#07070b');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);

  const R=Math.min(W,H)*0.33;
  const TH=R*0.11;
  const a=TAU*t;        // flip about the horizontal axis (one turn per loop)
  const b=2*TAU*t;      // spin about the vertical axis (two turns per loop)
  renderCoin(ctx,W/2,H/2,R,TH,a,b,PAL.hero,drawFrontHero,drawBackHero);
}

/* ===================== EDITIONS ===================== */
const editions=[];
function initEditions(){
  document.querySelectorAll('.edition').forEach((tile,i)=>{
    const key=tile.getAttribute('data-edition');
    const cv=tile.querySelector('.edition-canvas');
    const denom={bronze:'1,000',silver:'5,000',gold:'10,000',black:'25,000'}[key];
    editions.push({key,cv,ctx:cv.getContext('2d'),denom,phase:i*0.19,period:11000+i*1300});
  });
}
function renderEdition(item,ts){
  const cv=item.cv,ec=item.ctx,W=cv.width,H=cv.height;
  if(W===0||H===0) return;
  ec.setTransform(1,0,0,1,0,0);
  const bg=ec.createRadialGradient(W/2,H*0.42,5,W/2,H/2,W*0.72);
  bg.addColorStop(0,'#1b1c25');bg.addColorStop(1,'#0a0a10');
  ec.fillStyle=bg;ec.fillRect(0,0,W,H);
  const R=Math.min(W,H)*0.36,TH=R*0.13;
  const t2=((ts/item.period)+item.phase)%1;
  const a=0.5, b=TAU*t2;
  renderCoin(ec,W/2,H/2,R,TH,a,b,PAL[item.key],
    (c,r,p)=>drawFront(c,r,p),(c,r,p)=>drawBack(c,r,p,item.denom));
}

/* ===================== sizing ===================== */
function sizeCanvas(cv){
  const r=cv.getBoundingClientRect();
  const w=Math.max(1,Math.round(r.width*DPR)), h=Math.max(1,Math.round(r.height*DPR));
  if(cv.width!==w||cv.height!==h){cv.width=w;cv.height=h;}
}
function resize(){
  sizeCanvas(canvas);
  editions.forEach(e=>sizeCanvas(e.cv));
  render(lastT);
}
window.addEventListener('resize',resize);

/* ===================== animation loop ===================== */
const HERO_PERIOD=9000;
let paused=false, rafId=null, t0=null;
function frame(ts){
  if(paused) return;
  if(t0===null) t0=ts;
  const t=(((ts-t0)/HERO_PERIOD)%1+1)%1;
  render(t);
  for(const e of editions) renderEdition(e,ts);
  rafId=requestAnimationFrame(frame);
}

/* ===================== programmatic API ===================== */
window.demo={
  canvas:canvas,
  setTime(t){ t=Math.max(0,Math.min(1,+t||0)); render(t); },
  pause(){ paused=true; if(rafId){cancelAnimationFrame(rafId);rafId=null;} }
};

